CREATE TABLE custom_domains(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,workspace_id BIGINT UNSIGNED NOT NULL,hostname VARCHAR(255) NOT NULL,status ENUM('pending','active','error','suspended') NOT NULL DEFAULT 'pending',https_status ENUM('pending','active','error') NOT NULL DEFAULT 'pending',last_error TEXT NULL,last_checked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,UNIQUE KEY custom_domains_hostname_unique(hostname),KEY custom_domains_status_idx(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE abuse_reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,link_id BIGINT UNSIGNED NULL,reporter_email VARCHAR(320) NULL,reason ENUM('malware','phishing','spam','copyright','other') NOT NULL,details TEXT NULL,status ENUM('open','investigating','resolved','rejected') NOT NULL DEFAULT 'open',resolution TEXT NULL,resolved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE SET NULL,KEY abuse_status_created_idx(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE security_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(80) NOT NULL,severity ENUM('info','warning','high','critical') NOT NULL,source VARCHAR(255) NULL,description TEXT NOT NULL,status ENUM('open','resolved') NOT NULL DEFAULT 'open',resolved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY security_severity_status_idx(severity,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',published_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY announcements_status_idx(status,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
